#!/usr/bin/env python3
"""Standalone SGDK cartridge: food-art layout, immediate DMA and VRAM readback."""
from pathlib import Path
import hashlib,json,re,subprocess
r=Path(__file__).resolve().parents[1];o=r/'out/parity-audit/section-bonus-live-target';o.mkdir(parents=True,exist_ok=True)
sdk=Path('/Users/rester159/My_apps/portForge/tools/sgdk');sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
original=sha(r/'out/rom.bin')
(o/'main.c').write_text('#include <genesis.h>\n#include "arcade_food_world.h"\n#include "arcade_food_bonus.h"\n#include "arcade_bonus_art.h"\nvolatile u16 test_done,test_error,test_batches,test_words,test_split;\nstatic u16 sat[12];\n#define CHECK(x) do {if(!(x)&&!test_error)test_error=__LINE__;test_words++;}while(0)\nint main(bool hard){u16 grade,owner,i;ArcadeBonusAward award;(void)hard;\nVDP_setEnable(FALSE);VDP_setScreenWidth256();VDP_setPlaneSize(64,32,TRUE);SYS_doVBlankProcess();\nfor(grade=0;grade<7;grade++)for(owner=0;owner<2;owner++){\n arcade_food_world_begin();arcade_food_bonus_reset();\n /* A7D0 must preserve existing actor and unrelated descriptor state. */\n arcade_food_pickup.x=1234;arcade_food_pickup.owner=1;arcade_food_pickup.exit_latched=1;\n arcade_food_spawn.row=9;arcade_food_bonus_section(grade);\n CHECK(arcade_food_spawn.active==1 && arcade_food_spawn.phase==0 && arcade_food_spawn.placement==104 && arcade_food_spawn.row==9);\n CHECK(arcade_food_pickup.kind==10 && arcade_food_pickup.x==1234 && arcade_food_pickup.owner==1 && arcade_food_pickup.exit_latched==1);\n arcade_food_world_begin();arcade_food_bonus_reset();arcade_food_bonus_section(grade);\n arcade_food_bonus_step(0,1,1,1);CHECK(arcade_food_spawn.phase==0);\n arcade_food_bonus_step(0,0,0,1);CHECK(arcade_food_spawn.phase==0);\n arcade_food_bonus_step(0,0,1,1);\n arcade_food_bonus_step(8,0,1,1);arcade_food_bonus_background(0);SYS_doVBlankProcess();\n arcade_food_bonus_step(16,0,1,1);arcade_food_bonus_background(0);SYS_doVBlankProcess();\n CHECK(arcade_food_pickup.active==1 && arcade_food_pickup.x==264 && arcade_food_pickup.y==104 && arcade_food_pickup.timer==32);\n CHECK(arcade_food_bonus_contact(264,104,owner,0x1234,&award));\n CHECK(award.points==4000+grade*1000 && award.combat==0x1234 && award.event==(0x400|(12+grade)|(owner<<7)) && award.sound==5);\n CHECK(!arcade_food_bonus_contact(264,104,owner^1,0x1234,&award));\n arcade_food_bonus_step(17,0,1,0);\n CHECK(arcade_food_pickup.timer==95 && arcade_food_pickup.anim_timer==127 && arcade_food_pickup.attr==(owner?0xc3:0xc4) && arcade_food_pickup.code==(grade==6?47:53+grade));\n CHECK(arcade_food_bonus_sat(17,sat,0,3)==2);\n {u16 tile=65535;for(i=0;i<22;i++)if(arcade_bonus_frames[i].code==arcade_food_pickup.code){tile=owner?arcade_bonus_frames[i].owner2_tile:arcade_bonus_frames[i].tile;break;}\n CHECK(tile!=65535 && (sat[2]&2047)==tile);}\n for(i=0;i<96;i++)arcade_food_bonus_step(17,0,1,0);\n CHECK(!arcade_food_pickup.active && !arcade_food_carrier.active && !arcade_food_orb);\n}\n/* Ordinary and section bonuses share the original eight-collection count. */\narcade_food_world_begin();arcade_food_bonus_reset();\nfor(i=0;i<8;i++){\n if(i&1)arcade_food_bonus_section(i%7);else arcade_food_pickup.kind=1;\n arcade_food_pickup.active=1;arcade_food_pickup.x=100;arcade_food_pickup.y=104;\n CHECK(arcade_food_bonus_contact(100,104,i&1,0x1234,&award) && arcade_food_conversion_spawn.active==(i==7));\n}\nCHECK(arcade_food_conversion.kind==255 && arcade_food_conversion_spawn.phase==0 && arcade_food_conversion_spawn.placement==104);\n\ntest_batches=3;test_split=1;test_done=1;while(1)SYS_doVBlankProcess();return 0;}\n')
# Deliberately cross a real128KiB boundary during the first food-bank load.
s=(r/'src/arcade_food_art.c').read_text().replace('const u32 arcade_food_pixels[','const u32 __attribute__((section(".largeart"))) arcade_food_pixels[')
(o/'art.c').write_text(s)
flags=['-m68000','-DSGDK_GCC','-O2','-fno-builtin','-fomit-frame-pointer','-ffunction-sections','-fdata-sections','-fms-extensions','-I'+str(r/'inc'),'-I'+str(sdk/'inc'),'-I'+str(sdk/'res')]
objects=[]
for name,path in [('main',o/'main.c'),('art',o/'art.c'),('power',r/'src/arcade_powerup.c'),('powerart',r/'src/arcade_powerup_art.c'),('upload',r/'src/arcade_powerup_upload.c'),('bonus',r/'src/arcade_food_bonus.c'),('orb',r/'src/arcade_orb.c'),('special',r/'src/arcade_special_spawn.c'),('pickup',r/'src/arcade_pickup.c'),('reward',r/'src/arcade_rewards.c'),('difficulty',r/'src/arcade_difficulty.c'),('bonusart',r/'src/arcade_bonus_art.c'),('sat',r/'src/arcade_cell_sat.c'),('world',r/'src/arcade_food_world.c'),('barrier',r/'src/arcade_barrier.c'),('barrierstep',r/'src/arcade_barrier_step.c'),('barrierdata',r/'src/arcade_barrier_data.c'),('barrierupload',r/'src/arcade_barrier_upload.c'),('barrierposes',r/'src/arcade_barrier_pose_data.c'),('pool',r/'src/arcade_world_object_pool.c'),('objects',r/'src/arcade_world_objects.c'),('step',r/'src/arcade_food_step.c'),('patterns',r/'src/arcade_food_patterns.c'),('food',r/'src/arcade_food.c')]:
 obj=o/(name+'.o');subprocess.run(['m68k-elf-gcc',*flags,'-c',str(path),'-o',str(obj)],check=True);objects.append(obj)
subprocess.run(['m68k-elf-gcc','-m68000','-n','-T',str(sdk/'md.ld'),'-nostdlib',str(r/'out/sega.o'),*map(str,objects),str(sdk/'lib/libmd.a'),'-lgcc','-Wl,--gc-sections','-Wl,--section-start=.largeart=0x1ffc0','-o',str(o/'rom.out')],check=True)
subprocess.run(['m68k-elf-objcopy','-O','binary',str(o/'rom.out'),str(o/'rom.bin')],check=True)
b=bytearray((o/'rom.bin').read_bytes());b.extend(bytes((-len(b))%131072));b[0x18e:0x190]=(sum(int.from_bytes(b[i:i+2],'big')for i in range(0x200,len(b),2))&65535).to_bytes(2,'big');(o/'rom.bin').write_bytes(b)
nm=subprocess.check_output(['m68k-elf-nm',str(o/'rom.out')],text=True);syms={n:int(v,16)&0xffffff for v,n in re.findall(r'^([0-9a-fA-F]+)\s+\w\s+(\w+)\s*$',nm,re.M)}
# Pixel bank may be discarded: this test checks nametable words.
s='''local m=manager.machine.devices[":maincpu"].spaces.program;local frame=0;local terminal=false
emu.register_frame_done(function()
 if terminal then manager.machine:exit();return end;frame=frame+1
 if m:read_u16(DONE)==1 or frame>600 then
  terminal=true;local f=assert(io.open(RESULT,'w'));f:write(string.format('{"done":%d,"error":%d,"batches":%d,"words":%d,"marker":%d}',m:read_u16(DONE),m:read_u16(ERROR),m:read_u16(BATCHES),m:read_u16(WORDS),m:read_u16(SPLIT)));f:close();manager.machine:exit()
 end
end)
'''
for key,name in [('DONE','test_done'),('ERROR','test_error'),('BATCHES','test_batches'),('WORDS','test_words'),('SPLIT','test_split')]:s=re.sub(r'\b'+key+r'\b',str(syms[name]),s)
s=s.replace('RESULT',json.dumps(str(o/'results.json')));(o/'run.lua').write_text(s);(o/'results.json').unlink(missing_ok=True)
with(o/'mame.log').open('w')as f:subprocess.run(['mame','genesis','-cart',str(o/'rom.bin'),'-window','-nomaximize','-resolution','512x448','-video','none','-noreadconfig','-sound','none','-nothrottle','-skip_gameinfo','-autoboot_delay','0','-autoboot_script',str(o/'run.lua'),'-cfg_directory',str(o/'cfg'),'-nvram_directory',str(o/'nvram')],cwd=r,stdout=f,stderr=subprocess.STDOUT,check=True,timeout=90)
assert sha(r/'out/rom.bin')==original
d=json.loads((o/'results.json').read_text());d.update(rom_sha256=sha(o/'rom.bin'),native_sha256=sha(r/'src/arcade_food_bonus.c'),scope='Actual68000 live bonus owner: seven grades and both owners, precise request writes, spawn gates, same-tick birth, score/combat/event, duplicate rejection, score SAT and retirement. Section-stop caller still pending.')
(o/'results.json').write_text(json.dumps(d,indent=2)+'\n');print(json.dumps(d,indent=2));assert d['done']==1 and d['error']==0 and d['batches']==3 and d['words']==177
